using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so preserve it.
            entity.HasDiscriminator().HasValue("Blog");
            entity.Property<string>("$type").ToJsonProperty("Discriminator");

            // Breaking change 2: EF 9 changed id format from "EntityType|Key" to just "Key".
            // Existing documents use "Blog|1" format, so preserve it.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .ToJsonProperty("id")
                  .HasValueGenerator<LegacyIdValueGenerator>();

            // Breaking change 3: EF 9 removed support for HasIndex on Cosmos.
            // Cosmos DB does not support secondary indexes via EF Core; remove HasIndex.
            // (was: entity.HasIndex(b => b.Name) — removed)
        });
    }

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        // Breaking change 4: EF 9 uses sync-over-async gateway mode by default.
        // SyncJob calls SaveChanges() synchronously — either switch to async or
        // configure Gateway mode explicitly. Using async is recommended (see SyncJob).
    }
}

class Blog
{
    public string Id { get; set; }
    public string Name { get; set; }
}

// Value generator that preserves the legacy "Discriminator|Key" id format
using Microsoft.EntityFrameworkCore.ChangeTracking;
using Microsoft.EntityFrameworkCore.ValueGeneration;

class LegacyIdValueGenerator : ValueGenerator<string>
{
    public override bool GeneratesTemporaryValues => false;
    public override string Next(EntityEntry entry) =>
        $"Blog|{Guid.NewGuid()}";
}

